import sys,ast,json
sys.dont_write_bytecode=True
import additional_pfp_tests_remaining_audit as a
rows=[
('pfp/tests/__init__.py',1,'Package docstring only; no executable test or mathematical claim.'),
('pfp/tests/_po035_historical.py',59,'Full helper read. Two historical adapter snapshots are pinned by exact SHA256, remapped at import and executed with a customized importer; dispatch_deadline is replaced only after exec. This supports custody of supplied snapshot bytes, not their mathematical correctness or safety of transitive top-level effects. Importing this helper immediately executes both snapshots. Offline-only replacement does not guard effects occurring before replacement; no historical imports or execution performed by this audit.'),
('pfp/tests/crash_child.py',106,'Full abrupt-process child read. Scripted gateway and fixture-only encryption exercise intent/durable-response cut points using os._exit and trace interception. Portable process abort is explicitly distinguished from actual power-loss evidence. If executed it writes filesystem traces and imports external runtime owners; audit did not execute it. Unknown cut names do not select either abrupt cut. No provider success or native mathematics established.'),
('pfp/tests/offline_network_guard.py',14,'Full opt-in pytest plugin read. It globally replaces socket.socket.connect/connect_ex with a refusal function when explicitly loaded. It is not automatic suite containment and does not cover datagrams, DNS, subprocess/native transports or already obtained functions. No source execution.'),
('pfp/tests/pilot_custody_support.py',53,'Full custody assertion helper read. Safe-loaded dossier and spec receipts are checked for selected identifiers, SHA256 bindings, response usage and matching historical outcome fields; infrastructure-failure cases require absent response/witness and locked retries. It intentionally does not reissue the historical checker. Matching supplied status and raw custody do not establish task correctness, provider provenance or comprehensive schema validity.'),
('pfp/tests/installed_package_probe.py',704,'Full installed probe read in bounded chunks. It combines import/export and packaged-resource checks, synthetic typed CLI handoffs, ten source-bound historical challenge starts, a C054 dual-checker fixture/empty-answer control, matrix CLI help, fake-transport budget refusal, explicit native budget calls, HMAC custody and SQLite signed-tip delivery controls. Synthetic provenance and no model evidence are stated; no probe was executed by this audit because it imports broad external owners and invokes a supplied native executable. Arithmetic acceptance uses an independent 17*-9 predicate, while schema-only CLI controls intentionally accept a wrong integer as unverified. End-of-run module-origin predicate has an empty startswith prefix and therefore selects all modules, including allowed standard-library dependencies outside the installed target; see F001/C002. Positive labels are contingent on all assertions and supplied runtime, not a general PFP theorem.')]
