p='pfp/tests/installed_package_probe.py';tree=ast.parse('\n'.join(a.source(p)))
node=next(x for x in ast.walk(tree) if isinstance(x,ast.If) and x.lineno==688)
predicate=compile(ast.Expression(node.test),'<read-vetted-origin-predicate>','eval')
results={name:eval(predicate,{'name':name,'__builtins__':{}}) for name in ('engine','engine.child','json','pathlib','pytest','unrelated')}
