n['controls'].append({'id':'PFPTESTS-C002','rule':'installed_origin_filter_negative_control','status':'counterexample_observed','source_evidence':[{'path':p,'sha256':a.row(p)['sha256'],'lines':[682,696]}],'method':'Compile and evaluate only the already read AST predicate; no imports or main execution from the target.','results':results,'limits':'All tested non-production names are selected due to empty prefix; actual installed/native probe not run.'})
n['findings'].append({'id':'PFPTESTS-F001','severity':'medium','statement':'Installed package origin filter selects every imported module and rejects normal external standard-library dependencies.','evidence':[{'path':p,'sha256':a.row(p)['sha256'],'lines':[682,696]}],'reason':'name.startswith(("engine.", "")) is true for every string. The following assertions require every selected file and namespace path to reside under installed, although the probe explicitly permits dependencies from the invoking environment. Standard-library json/pathlib are selected too.','control':'PFPTESTS-C002','limits':'A source-level predicate counterexample; no distribution build or supplied native executable was run.'})
